{
  "subevents": [
    {
      "id": "0",
      "subevent": "Looting, arson, attacks on police stations and vehicles, destruction of an ambulance, and daily protests ending in clashes with security forces have occurred in Chile."
    },
    {
      "id": "1",
      "subevent": "President Sebastian Pinera sent an urgent bill to Congress requesting the army be allowed to safeguard key installations without declaring a state of emergency."
    },
    {
      "id": "2",
      "subevent": "The government stated that about one-third of the estimated $1.5bn destruction was caused by criminal gangs, common criminals, drug traffickers and anarchists."
    },
    {
      "id": "3",
      "subevent": "Graffiti messages such as 'Accumulate fury' and 'make the cuicos (the rich) shiver' were seen in Santiago."
    },
    {
      "id": "4",
      "subevent": "A protester named Mario said that peaceful demonstrations have achieved nothing."
    },
    {
      "id": "5",
      "subevent": "Mario lost his job as an assistant accountant."
    },
    {
      "id": "6",
      "subevent": "Maria said that they need to shake the elite out of their comfort zone and make them feel fear to force action."
    },
    {
      "id": "7",
      "subevent": "Maria said that the rich and powerful threw the first stone by discriminating and leaving them without education and healthcare."
    },
    {
      "id": "8",
      "subevent": "Maria Olga said that those causing destruction cannot be Chileans and she does not recognize the country."
    },
    {
      "id": "9",
      "subevent": "Mario said they are not asking for jewels or gold, only basic things like a decent income and basic services."
    },
    {
      "id": "10",
      "subevent": "Maria expressed anger at the injustice she sees, such as her mother being unable to get hospital treatment for her grandparents and the huge differences in standard of living."
    },
    {
      "id": "11",
      "subevent": "A new study showed that 58 percent of Chileans belong to the lower-middle-class or 'vulnerable class' who cannot access their basic needs under the current system."
    },
    {
      "id": "12",
      "subevent": "Mario said he does not believe in voting and does not feel represented by any political party."
    }
  ]
}

{
  "subevents": [
    {
      "id": "0",
      "subevent": "A double-decker bus overturned into a field in Devon on Saturday 5 October."
    },
    {
      "id": "1",
      "subevent": "Emergency services declared a major incident after the crash on the A385 between Totnes and Paignton at around 11am."
    },
    {
      "id": "2",
      "subevent": "A multi-agency approach was adopted by emergency services, deploying a large number of police, fire, and ambulance vehicles."
    },
    {
      "id": "3",
      "subevent": "Numerous air ambulances attended the scene."
    },
    {
      "id": "4",
      "subevent": "At 5:30pm, Devon and Cornwall Police released a statement."
    },
    {
      "id": "5",
      "subevent": "The statement said that 37 people sustained injuries, with eight described as having potentially serious injuries."
    },
    {
      "id": "6",
      "subevent": "Police confirmed that the road will close again from 7am on Sunday 6 October while emergency crews recover the bus."
    },
    {
      "id": "7",
