{
  "subevents": [
    {
      "id": "0",
      "subevent": "The X-37B Orbital Test Vehicle Mission 5 landed at NASA's Kennedy Space Center Shuttle Landing Facility on Oct. 27, 2019, at 3:51 a.m."
